    /// Returns launch, confinement or missing-pipe failures.
    pub(super) fn spawn(
        client: &OmpClient,
        cwd: &str,
        args: &[String],
        confinement: Option<&domain::workspace::sandbox::WriteConfinement>,
    ) -> Result<Self, AgentSessionError> {
