        let mut command = crate::local::sandbox::command(
            &client.program,
            confinement,
            crate::local::sandbox::OMP_STATE,
            &|name| client.environment.variable(name),
        )?;
        command
            .args(args)
            .current_dir(cwd)
            .envs(client.environment.entries())
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .kill_on_drop(true);
        #[cfg(unix)]
        command.process_group(0);
        let mut child = command
            .spawn()
